/// <summary>
/// Initializes the query for the UnitOfMeasureConversion form.
/// </summary>
public void init()
{
    QueryBuildDataSource qbdsUnitOfMeasureConversion;
    QueryBuildRange qbrProduct;
    EcoResDistinctProductVariant distinctProductVariant;

    next init();

    distinctProductVariant = element.args().record() as EcoResDistinctProductVariant;

    qbdsUnitOfMeasureConversion = this.query().dataSourceTable(tableNum(UnitOfMeasureConversion));
    qbdsUnitOfMeasureConversion.clearDynalinks();

    if (element.args() && element.args().record())
    {
        qbrProduct = qbdsUnitOfMeasureConversion.addRange(fieldNum(UnitOfMeasureConversion, Product));
        qbrProduct.value(Global::queryRangeConcat(Global::queryValue(distinctProductVariant.RecId), 0));
    }
    else
    {
        qbdsUnitOfMeasureConversion.addSortField(fieldNum(UnitOfMeasureConversion, Product));
    }

    qbdsUnitOfMeasureConversion.addSortField(fieldNum(UnitOfMeasureConversion, Factor));

    this.cacheAddMethod(tableMethodStr(UnitOfMeasureConversion, displayQuickFormula));
}
